package com.wayrapass.service;import com.wayrapass.dto.request.UpdateUserProfileRequest;import com.wayrapass.dto.response.UserResponse;import com.wayrapass.model.User;import com.wayrapass.repository.UserRepository;import com.wayrapass.security.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class UserProfileService{private final CurrentUser current;private final UserRepository users;@Transactional(readOnly=true)public UserResponse me(){return out(current.require());}@Transactional public UserResponse update(UpdateUserProfileRequest r){User u=current.require();u.setFullName(r.fullName().trim());u.setPhone(r.phone()==null||r.phone().isBlank()?null:r.phone().trim());return out(users.save(u));}private UserResponse out(User u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getPhone(),u.getRole(),u.isEnabled(),u.getCreatedAt(),u.getUpdatedAt());}}
